using System.Net.Http.Json;
using System.Text.Json;
using SalekhPos.Desktop.Application.Management;
namespace SalekhPos.Desktop.Infrastructure.Management; public sealed class HttpFiscalizationManager(HttpClient client) : IFiscalizationManager { private static readonly JsonSerializerOptions Json = new(JsonSerializerDefaults.Web); public async Task<DesktopFiscalDocument> ReadAsync(Guid org, Guid id, CancellationToken ct) { Ids(org, id); using var r = await client.GetAsync($"api/v1/organizations/{org:D}/fiscal-documents/{id:D}", ct); r.EnsureSuccessStatusCode(); var v = await r.Content.ReadFromJsonAsync<DesktopFiscalDocument>(Json, ct) ?? throw new InvalidOperationException("Empty fiscal response."); Validate(v, id); return v; } public async Task<DesktopFiscalSubmission> SubmitAsync(Guid org, Guid branch, DesktopFiscalInput input, CancellationToken ct) { Ids(org, branch, input.DocumentId, input.SaleId); using var r = await client.PostAsJsonAsync($"api/v1/organizations/{org:D}/fiscal-documents/branches/{branch:D}", input, Json, ct); r.EnsureSuccessStatusCode(); var v = await r.Content.ReadFromJsonAsync<DesktopFiscalSubmission>(Json, ct) ?? throw new InvalidOperationException("Empty fiscal response."); Validate(v.Document, input.DocumentId); if (v.Document.BranchId != branch) throw new InvalidOperationException("Fiscal branch changed."); return v; } public async Task<DesktopFiscalSubmission> RetryAsync(Guid org, Guid id, CancellationToken ct) { Ids(org, id); using var r = await client.PostAsJsonAsync($"api/v1/organizations/{org:D}/fiscal-documents/{id:D}/retry", new { }, Json, ct); r.EnsureSuccessStatusCode(); var v = await r.Content.ReadFromJsonAsync<DesktopFiscalSubmission>(Json, ct) ?? throw new InvalidOperationException("Empty fiscal response."); Validate(v.Document, id); return v; } private static void Validate(DesktopFiscalDocument v, Guid id) { if (v.DocumentId != id || v.BranchId == Guid.Empty || v.SaleId == Guid.Empty || v.Currency.Length != 3 || v.GrossAmount < 0 || v.PayloadSha256.Length != 64 || v.PayloadSha256.Any(c => !Uri.IsHexDigit(c)) || v.AttemptCount < 0 || v.Attempts.Count > 100) throw new InvalidOperationException("Fiscal response is invalid."); } private static void Ids(params Guid[] ids) { if (ids.Any(x => x == Guid.Empty)) throw new ArgumentException("Fiscal identifiers are required."); } }
